module synchronizer(
    input clk_a, clk_b, arstn, brstn, data_en,
    input [3:0] data_in,
    output reg [3:0] dataout
);
    // Register data_reg stores input data data_in.
    // It is updated on the positive edge of clk_a or the negative edge of arstn.
    // When arstn is low, data_reg is set to 0.
    // When arstn is high, data_reg is updated with data_in.
    reg [3:0] data_reg;
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) data_reg <= 4'd0;
        else        data_reg <= data_in;
    end
    // Register en_data_reg stores input enable signal data_en.
    // It is updated on the positive edge of clk_a or the negative edge of arstn.
    // When arstn is low, en_data_reg is set to 0.
    // When arstn is high, en_data_reg is updated with data_en.
    reg [3:0] en_data_reg;
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) en_data_reg <= 4'd0;
        else        en_data_reg <= data_en;
    end
    // Registers en_clap_one and en_clap_two control the selection of input data.
    // They are updated on the positive edge of clk_b or the negative edge of brstn.
    // When brstn is low, both en_clap_one and en_clap_two are set to 0.
    // When brstn is high, en_clap_one is updated with en_data_reg, and en_clap_two is updated with en_clap_one.
    reg [3:0] en_clap_one, en_clap_two;
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            en_clap_one <= 4'd0;
            en_clap_two <= 4'd0;
        end else begin
            en_clap_one <= en_data_reg;
            en_clap_two <= en_clap_one;
        end
    end
    // Output dataout is assigned on the positive edge of clk_b or the negative edge of brstn.
    // When brstn is low, dataout is set to 0.
    // When brstn is high, if en_clap_two is active, dataout is updated with data_reg.
    // Otherwise, dataout retains its previous value.
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) dataout <= 4'd0;
        else if (en_clap_two) dataout <= data_reg;
        else dataout <= dataout;
    end
endmodule
